mat2 rot(float a) { float s = sin(a), c = cos(a); return mat2(c, -s, s, c); }
float map(vec3 p) {
  for (int i = 0; i < 3; i++) {
    p = abs(p) - 0.7;
    p.xy = rot(0.5) * p.xy;
    p.xz = rot(time * 0.2) * p.xz;
  }
  return length(p) - 0.25;
}
shader_body {
  vec2 p = (uv - 0.5) * vec2(aspect.x, 1.0) * 2.0;
  vec3 ro = vec3(0.0, 0.0, -3.0);
  vec3 rd = normalize(vec3(p, 1.5));
  float t = 0.0;
  for (int i = 0; i < 48; i++) {
    float d = map(ro + rd * t);
    if (d < 0.003 || t > 8.0) break;
    t += d * 0.75;
  }
  vec3 col = vec3(0.02, 0.01, 0.04);
  if (t < 8.0) {
    vec3 pos = ro + rd * t;
    vec3 n = normalize(pos);
    float rim = pow(1.0 - max(dot(n, -rd), 0.0), 2.5);
    col = vec3(0.05, 0.02, 0.1) + rim * vec3(1.0, 0.2, 0.8) + vec3(0.2, 0.8, 1.0) * max(dot(n, vec3(0, 1, 0)), 0.0);
  }
  ret = col;
}
